args.command:
cd /workspace; run(){ echo "== $*"; env -i PATH=/usr/bin:/bin HOME=/tmp/fakehome TERM=xterm ./executable "$@" /dev/null 2>&1; echo "exit=$?"; }
run --tabs 0; run --tabs -1; run --tabs abc; run --tabs 2.5; run --tabs 99999999999999999999; run --tabs=8; run -r 1:3 --tabs 4
for v in "1:" ":3" ":" "3:1" "a:b" "1:2:3" "+" "+3" "-2" "--" "1,2" " 1 : 3 " "1"; do run --line-range "$v"; done

